-- ----------------------------
-- Table structure for ai_model
-- ----------------------------
DROP TABLE IF EXISTS `ai_model`;
CREATE TABLE `ai_model`  (
  `id` bigint NOT NULL COMMENT '主键',
  `model_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '模型名称（请求模型名，如 qwen-plus）',
  `model_type` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'LLM/EMBEDDING/TTS',
  `base_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'api地址',
  `api_key` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'api密钥',
  `temperature` decimal(3, 2) NULL DEFAULT NULL COMMENT '模型温度',
  `top_p` decimal(3, 2) NULL DEFAULT NULL COMMENT '词汇属性',
  `presence_penalty` decimal(3, 2) NULL DEFAULT NULL COMMENT '话题属性',
  `frequency_penalty` decimal(3, 2) NULL DEFAULT NULL COMMENT '重复属性',
  `max_tokens` int NULL DEFAULT NULL COMMENT '最大回复',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `sort_order` int NULL DEFAULT 0 COMMENT '排序',
  `is_active` tinyint NULL DEFAULT 0 COMMENT '是否启用：1-启用，0-未启用',
  `is_deleted` tinyint NULL DEFAULT 0 COMMENT '是否删除',
  `gmt_create` datetime NULL DEFAULT NULL,
  `gmt_modified` datetime NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_ai_model_type`(`model_type` ASC, `is_active` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'AI模型配置' ROW_FORMAT = Dynamic;

