-- ----------------------------
-- Table structure for ap_ad_watch_record
-- ----------------------------
DROP TABLE IF EXISTS `ap_ad_watch_record`;
CREATE TABLE `ap_ad_watch_record`  (
  `id` bigint NOT NULL COMMENT '记录ID，雪花算法生成',
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `user_nickname` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '用户昵称（冗余）',
  `ad_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '广告ID',
  `ad_platform` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '广告平台：uni-ad/腾讯广告/穿山甲等',
  `ad_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '广告类型：rewarded_video-激励视频，banner-横幅等',
  `ad_position` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '广告位标识',
  `watch_date` datetime NOT NULL COMMENT '观看日期',
  `reward_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '奖励类型：vip_days-会员天数，points-积分等',
  `reward_amount` int NOT NULL DEFAULT 0 COMMENT '奖励数量',
  `reward_status` tinyint NOT NULL DEFAULT 0 COMMENT '奖励发放状态：0-未发放，1-已发放，2-发放失败',
  `device_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '设备ID',
  `platform_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'mp-weixin' COMMENT '平台类型：mp-weixin/app-plus/h5',
  `ip_address` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT 'IP地址',
  `user_agent` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '用户代理',
  `is_deleted` tinyint NOT NULL DEFAULT 0 COMMENT '是否删除：0-未删除，1-已删除',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_id`(`user_id` ASC) USING BTREE,
  INDEX `idx_ad_id`(`ad_id` ASC) USING BTREE,
  INDEX `idx_watch_date`(`watch_date` ASC) USING BTREE,
  INDEX `idx_ad_platform`(`ad_platform` ASC) USING BTREE,
  INDEX `idx_ad_type`(`ad_type` ASC) USING BTREE,
  INDEX `idx_reward_status`(`reward_status` ASC) USING BTREE,
  INDEX `idx_platform_type`(`platform_type` ASC) USING BTREE,
  INDEX `idx_user_date`(`user_id` ASC, `watch_date` ASC) USING BTREE,
  INDEX `idx_is_deleted`(`is_deleted` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '广告观看记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of ap_ad_watch_record
-- ----------------------------

-- ----------------------------
-- Table structure for ap_comment_audit_log
-- ----------------------------
DROP TABLE IF EXISTS `ap_comment_audit_log`;
CREATE TABLE `ap_comment_audit_log`  (
  `id` bigint NOT NULL COMMENT '日志ID，雪花算法生成',
  `comment_id` bigint NOT NULL COMMENT '评论ID',
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `audit_status` tinyint NOT NULL COMMENT '审核状态：0-待审核，1-审核通过，2-审核不通过',
  `audit_user_id` bigint NULL DEFAULT NULL COMMENT '审核人ID',
  `audit_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '审核时间',
  `audit_remark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '审核备注',
  `is_deleted` tinyint NOT NULL DEFAULT 0 COMMENT '是否删除：0-未删除，1-已删除',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_comment_id`(`comment_id` ASC) USING BTREE,
  INDEX `idx_user_id`(`user_id` ASC) USING BTREE,
  INDEX `idx_audit_status`(`audit_status` ASC) USING BTREE,
  INDEX `idx_audit_user_id`(`audit_user_id` ASC) USING BTREE,
  INDEX `idx_is_deleted`(`is_deleted` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '评论审核日志表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of ap_comment_audit_log
-- ----------------------------

-- ----------------------------
-- Table structure for ap_drive_question
-- ----------------------------
DROP TABLE IF EXISTS `ap_drive_question`;
CREATE TABLE `ap_drive_question`  (
  `id` bigint NOT NULL COMMENT '题目ID，雪花算法生成',
  `subject` tinyint NOT NULL COMMENT '科目：1-科目一，4-科目四',
  `exam_type` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '学科类型：c1、c2、a1、a2、b1等',
  `question_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '题型代码：traffic_signs-交通标志，traffic_rules-交通法规等',
  `question_type_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '题型名称',
  `question_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '题目内容',
  `question_format` tinyint NOT NULL DEFAULT 1 COMMENT '题目格式：1-选择题，2-判断题，3-多选题',
  `option_a` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '选项A',
  `option_b` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '选项B',
  `option_c` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '选项C',
  `option_d` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '选项D',
  `correct_answer` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '正确答案：单选:1/2/3/4,多选:1,2,3',
  `question_explain` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '题目解析',
  `image_url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '题目配图URL',
  `video_url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '题目视频URL',
  `audio_url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '题目音频URL',
  `difficulty_level` tinyint NOT NULL DEFAULT 1 COMMENT '难度等级：1-简单，2-中等，3-困难',
  `is_vip` tinyint NOT NULL DEFAULT 0 COMMENT '是否VIP题目：0-免费，1-VIP',
  `is_hot` tinyint NOT NULL DEFAULT 0 COMMENT '是否热门题目：0-否，1-是',
  `sequence_order` int NOT NULL DEFAULT 0 COMMENT '顺序刷题排序',
  `weight` int NOT NULL DEFAULT 1 COMMENT '题目权重',
  `tags` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '题目标签，逗号分隔',
  `knowledge_points` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '知识点，逗号分隔',
  `view_count` bigint NOT NULL DEFAULT 0 COMMENT '浏览次数',
  `error_count` bigint NOT NULL DEFAULT 0 COMMENT '错误次数',
  `correct_count` bigint NOT NULL DEFAULT 0 COMMENT '正确次数',
  `correct_rate` decimal(5, 2) NOT NULL DEFAULT 0.00 COMMENT '正确率',
  `avg_answer_time` decimal(5, 2) NOT NULL DEFAULT 0.00 COMMENT '平均答题时间(秒)',
  `source` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'official' COMMENT '题目来源：official-官方，user-用户贡献',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '题目状态：0-下架，1-可用，2-审核中',
  `creator_id` bigint NULL DEFAULT NULL COMMENT '创建者ID',
  `auditor_id` bigint NULL DEFAULT NULL COMMENT '审核者ID',
  `audit_time` datetime NULL DEFAULT NULL COMMENT '审核时间',
  `is_deleted` tinyint NOT NULL DEFAULT 0 COMMENT '是否删除：0-未删除，1-已删除',
  `gmt_create` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `gmt_modified` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_subject`(`subject` ASC) USING BTREE,
  INDEX `idx_question_type`(`question_type` ASC) USING BTREE,
  INDEX `idx_difficulty_level`(`difficulty_level` ASC) USING BTREE,
  INDEX `idx_sequence_order`(`sequence_order` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE,
  INDEX `idx_is_hot`(`is_hot` ASC) USING BTREE,
  INDEX `idx_weight`(`weight` ASC) USING BTREE,
  INDEX `idx_view_count`(`view_count` ASC) USING BTREE,
  INDEX `idx_correct_rate`(`correct_rate` ASC) USING BTREE,
  INDEX `idx_creator_id`(`creator_id` ASC) USING BTREE,
  INDEX `idx_is_deleted`(`is_deleted` ASC) USING BTREE,
  INDEX `idx_subject_exam_tags`(`subject` ASC, `exam_type` ASC, `tags` ASC, `id` ASC) USING BTREE,
  INDEX `idx_subject_exam_id`(`subject` ASC, `exam_type` ASC, `id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '驾考题目表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of ap_drive_question
-- ----------------------------

-- ----------------------------
-- Table structure for ap_exam_plan
-- ----------------------------
DROP TABLE IF EXISTS `ap_exam_plan`;
CREATE TABLE `ap_exam_plan`  (
  `id` bigint NOT NULL COMMENT '主键',
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `exam_type` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'c1' COMMENT '车型',
  `subject` tinyint NOT NULL DEFAULT 1 COMMENT '科目：1科目一，4科目四',
  `exam_date` date NOT NULL COMMENT '计划考试日期',
  `target_score` int NOT NULL DEFAULT 90 COMMENT '目标分数',
  `daily_goal` int NOT NULL DEFAULT 20 COMMENT '每日题量',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `gmt_create` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `gmt_modified` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_exam_plan_user`(`user_id` ASC, `gmt_modified` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '考试计划' ROW_FORMAT = Dynamic;

