-- ----------------------------
-- Table structure for ap_exam_record
-- ----------------------------
DROP TABLE IF EXISTS `ap_exam_record`;
CREATE TABLE `ap_exam_record`  (
  `id` bigint NOT NULL COMMENT '考试ID，雪花算法生成',
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `user_nickname` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '用户昵称（冗余）',
  `subject` tinyint NOT NULL COMMENT '考试科目：1-科目一，4-科目四',
  `total_questions` int NOT NULL DEFAULT 100 COMMENT '总题数',
  `answered_questions` int NOT NULL DEFAULT 0 COMMENT '已答题数',
  `correct_count` int NOT NULL DEFAULT 0 COMMENT '正确题数',
  `wrong_count` int NOT NULL DEFAULT 0 COMMENT '错误题数',
  `score` decimal(5, 2) NOT NULL DEFAULT 0.00 COMMENT '得分',
  `pass_score` decimal(5, 2) NOT NULL DEFAULT 90.00 COMMENT '及格分数',
  `is_pass` tinyint NOT NULL DEFAULT 0 COMMENT '是否通过：0-未通过，1-通过',
  `exam_duration` int NOT NULL DEFAULT 2700 COMMENT '考试时长（秒）',
  `used_time` int NOT NULL DEFAULT 0 COMMENT '已用时间（秒）',
  `remaining_time` int NOT NULL DEFAULT 0 COMMENT '剩余时间（秒）',
  `exam_status` tinyint NOT NULL DEFAULT 0 COMMENT '考试状态：0-进行中，1-已完成，2-已放弃',
  `start_time` datetime NULL DEFAULT NULL COMMENT '开始时间',
  `submit_time` datetime NULL DEFAULT NULL COMMENT '提交时间',
  `is_deleted` tinyint NOT NULL DEFAULT 0 COMMENT '是否删除：0-未删除，1-已删除',
  `gmt_create` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `gmt_modified` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改旲间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_id`(`user_id` ASC) USING BTREE,
  INDEX `idx_subject`(`subject` ASC) USING BTREE,
  INDEX `idx_exam_status`(`exam_status` ASC) USING BTREE,
  INDEX `idx_is_pass`(`is_pass` ASC) USING BTREE,
  INDEX `idx_gmt_create`(`gmt_create` ASC) USING BTREE,
  INDEX `idx_is_deleted`(`is_deleted` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '考试记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of ap_exam_record
-- ----------------------------

