-- ----------------------------
-- Table structure for ap_mall_goods
-- ----------------------------
DROP TABLE IF EXISTS `ap_mall_goods`;
CREATE TABLE `ap_mall_goods`  (
  `id` bigint NOT NULL,
  `goods_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `goods_type` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'VIRTUAL 虚拟，PHYSICAL 实物',
  `category` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `cover_image` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '封面图片URL',
  `cover_text` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `summary` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `points_price` int NOT NULL DEFAULT 0 COMMENT '积分价',
  `cash_price` int NOT NULL DEFAULT 0 COMMENT '现金价，单位分',
  `reward_type` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'NONE' COMMENT 'NONE 或 VIP_DAYS',
  `reward_value` int NOT NULL DEFAULT 0,
  `stock` int NOT NULL DEFAULT 0,
  `status` tinyint NOT NULL DEFAULT 1,
  `sort_order` int NOT NULL DEFAULT 0,
