-- Table structure for ap_mall_order
-- ----------------------------
DROP TABLE IF EXISTS `ap_mall_order`;
CREATE TABLE `ap_mall_order`  (
  `id` bigint NOT NULL,
  `order_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `user_id` bigint NOT NULL,
  `order_type` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'GOODS 商品，VIP 会员',
  `goods_id` bigint NULL DEFAULT NULL,
  `plan_id` bigint NULL DEFAULT NULL,
  `goods_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `goods_type` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'VIRTUAL PHYSICAL VIP',
  `pay_type` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'POINTS 积分，WECHAT 微信支付',
  `points_cost` int NOT NULL DEFAULT 0,
  `cash_amount` int NOT NULL DEFAULT 0 COMMENT '单位分',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '0待支付 1待发货 2已发货 3已完成 4已取消',
  `receiver_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `receiver_phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `receiver_address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `express_company` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `express_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `pay_time` datetime NULL DEFAULT NULL,
  `ship_time` datetime NULL DEFAULT NULL,
  `finish_time` datetime NULL DEFAULT NULL,
  `gmt_create` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `gmt_modified` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_mall_order_no`(`order_no` ASC) USING BTREE,
  INDEX `idx_mall_order_user`(`user_id` ASC, `status` ASC, `gmt_create` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '商城与会员订单' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of ap_mall_order
-- ----------------------------

-- ----------------------------
-- Table structure for ap_member_plan
-- ----------------------------
DROP TABLE IF EXISTS `ap_member_plan`;
CREATE TABLE `ap_member_plan`  (
  `id` bigint NOT NULL,
  `plan_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `days` int NOT NULL,
  `price` int NOT NULL COMMENT '售价，单位分',
  `origin_price` int NOT NULL DEFAULT 0 COMMENT '原价，单位分',
  `points_reward` int NOT NULL DEFAULT 0 COMMENT '开通成功赠送积分',
  `recommended` tinyint NOT NULL DEFAULT 0,
  `status` tinyint NOT NULL DEFAULT 1,
  `sort_order` int NOT NULL DEFAULT 0,
  `gmt_create` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '会员套餐' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of ap_member_plan
-- ----------------------------

-- ----------------------------
-- Table structure for ap_points_exchange_record
-- ----------------------------
DROP TABLE IF EXISTS `ap_points_exchange_record`;
CREATE TABLE `ap_points_exchange_record`  (
  `id` bigint NOT NULL COMMENT '兑换记录ID，雪花算法生成',
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `user_nickname` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '用户昵称（冗余）',
  `user_phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '用户手机号（冗余）',
  `product_id` bigint NOT NULL COMMENT '商品ID',
  `product_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '商品名称（冗余）',
  `product_image` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '商品图片（冗余）',
  `points_cost` int NOT NULL COMMENT '消耗积分',
  `exchange_quantity` int NOT NULL DEFAULT 1 COMMENT '兑换数量',
  `delivery_info` json NULL COMMENT '配送信息JSON',
  `exchange_status` tinyint NOT NULL DEFAULT 0 COMMENT '兑换状态：0-待处理，1-已发货，2-已完成，3-已取消',
  `remark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '备注',
  `is_deleted` tinyint NOT NULL DEFAULT 0 COMMENT '是否删除：0-未删除，1-已删除',
  `gmt_create` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '兑换时间',
  `gmt_modified` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_id`(`user_id` ASC) USING BTREE,
  INDEX `idx_product_id`(`product_id` ASC) USING BTREE,
  INDEX `idx_exchange_status`(`exchange_status` ASC) USING BTREE,
  INDEX `idx_gmt_create`(`gmt_create` ASC) USING BTREE,
  INDEX `idx_is_deleted`(`is_deleted` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '积分兑换记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of ap_points_exchange_record
-- ----------------------------

-- ----------------------------
-- Table structure for ap_points_log
-- ----------------------------
DROP TABLE IF EXISTS `ap_points_log`;
CREATE TABLE `ap_points_log`  (
  `id` bigint NOT NULL,
  `user_id` bigint NOT NULL,
  `scene_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `points` int NOT NULL COMMENT '正数为获得，负数为消耗',
  `balance` int NOT NULL COMMENT '变动后余额',
  `biz_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '业务单号，用于去重',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `gmt_create` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_points_user`(`user_id` ASC, `gmt_create` ASC) USING BTREE,
  INDEX `idx_points_biz`(`user_id` ASC, `scene_code` ASC, `biz_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '积分流水' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of ap_points_log
-- ----------------------------

-- ----------------------------
-- Table structure for ap_points_mall_product
-- ----------------------------
DROP TABLE IF EXISTS `ap_points_mall_product`;
CREATE TABLE `ap_points_mall_product`  (
  `id` bigint NOT NULL COMMENT '商品ID，雪花算法生成',
  `product_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '商品名称',
  `product_desc` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '商品描述',
  `product_image` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '商品图片URL',
  `product_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '商品类型：course-课程，vip-VIP会员，gift-实物礼品',
  `points_price` int NOT NULL COMMENT '积分价格',
  `original_price` decimal(10, 2) NULL DEFAULT NULL COMMENT '原价',
  `stock_quantity` int NOT NULL DEFAULT -1 COMMENT '库存数量，-1表示无限',
  `exchange_limit` int NOT NULL DEFAULT -1 COMMENT '兑换限制，-1表示无限制',
  `is_hot` tinyint NOT NULL DEFAULT 0 COMMENT '是否热门：0-否，1-是',
  `sort_order` int NOT NULL DEFAULT 0 COMMENT '排序权重',
  `is_deleted` tinyint NOT NULL DEFAULT 0 COMMENT '是否删除：0-未删除，1-已删除',
  `gmt_create` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `gmt_modified` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_product_type`(`product_type` ASC) USING BTREE,
  INDEX `idx_is_deleted`(`is_deleted` ASC) USING BTREE,
  INDEX `idx_is_hot`(`is_hot` ASC) USING BTREE,
  INDEX `idx_sort_order`(`sort_order` ASC) USING BTREE,
  INDEX `idx_points_price`(`points_price` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '积分商城商品表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of ap_points_mall_product
-- ----------------------------

-- ----------------------------
-- Table structure for ap_points_rule
-- ----------------------------
DROP TABLE IF EXISTS `ap_points_rule`;
CREATE TABLE `ap_points_rule`  (
  `id` bigint NOT NULL COMMENT '主键',
  `scene_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '场景编码',
  `scene_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '场景名称',
  `points` int NOT NULL DEFAULT 0 COMMENT '固定积分，calc_type=FEN 时忽略',
  `calc_type` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'FIXED' COMMENT 'FIXED 固定积分，FEN 按实付金额每元1积分',
  `daily_limit` int NOT NULL DEFAULT 0 COMMENT '每天最多发放次数，0 表示不按天限制',
  `enabled` tinyint NOT NULL DEFAULT 1 COMMENT '1启用',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `gmt_create` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_points_scene`(`scene_code` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '积分发放规则' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of ap_points_rule
-- ----------------------------

-- ----------------------------
-- Table structure for ap_practice_progress
-- ----------------------------
DROP TABLE IF EXISTS `ap_practice_progress`;
CREATE TABLE `ap_practice_progress`  (
  `id` bigint NOT NULL COMMENT '主键',
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `subject` tinyint NOT NULL COMMENT '科目',
  `exam_type` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '车型',
  `question_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '题型，空表示全部',
  `last_index` int NOT NULL DEFAULT 0 COMMENT '上次做到的下标',
  `answered_count` int NOT NULL DEFAULT 0 COMMENT '已答题数',
  `correct_count` int NOT NULL DEFAULT 0 COMMENT '答对题数',
  `gmt_create` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `gmt_modified` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_user_progress`(`user_id` ASC, `subject` ASC, `exam_type` ASC, `question_type` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '顺序练习进度，刷题列表接口不读这张表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of ap_practice_progress
-- ----------------------------

-- ----------------------------
-- Table structure for ap_study_checkin
-- ----------------------------
DROP TABLE IF EXISTS `ap_study_checkin`;
CREATE TABLE `ap_study_checkin`  (
  `id` bigint NOT NULL COMMENT '主键',
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `checkin_date` date NOT NULL COMMENT '打卡日期',
  `subject` tinyint NOT NULL DEFAULT 1 COMMENT '科目：1科目一，4科目四',
  `exam_type` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'c1' COMMENT '车型',
  `question_count` int NOT NULL DEFAULT 0 COMMENT '完成题数',
  `correct_count` int NOT NULL DEFAULT 0 COMMENT '答对题数',
  `gmt_create` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `gmt_modified` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_user_date_subject`(`user_id` ASC, `checkin_date` ASC, `subject` ASC, `exam_type` ASC) USING BTREE,
  INDEX `idx_user_date`(`user_id` ASC, `checkin_date` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '学习打卡' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of ap_study_checkin
-- ----------------------------

-- ----------------------------
-- Table structure for ap_traffic_sign
-- ----------------------------
DROP TABLE IF EXISTS `ap_traffic_sign`;
CREATE TABLE `ap_traffic_sign`  (
  `id` bigint NOT NULL COMMENT '标志ID，雪花算法生成',
  `sign_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '标志名称',
  `sign_desc` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '标志说明',
  `sign_image` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '标志图片URL',
  `sign_category` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '标志类别：warning-警告标志，prohibition-禁令标志等',
  `sign_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '标志类型',
  `usage_scene` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '使用场景',
  `related_regulations` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '相关法规',
  `sort_order` int NOT NULL DEFAULT 0 COMMENT '排序权重',
  `view_count` bigint NOT NULL DEFAULT 0 COMMENT '查看次数',
  `is_deleted` tinyint NOT NULL DEFAULT 0 COMMENT '是否删除：0-未删除，1-已删除',
  `gmt_create` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `gmt_modified` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_sign_category`(`sign_category` ASC) USING BTREE,
  INDEX `idx_sign_type`(`sign_type` ASC) USING BTREE,
  INDEX `idx_is_deleted`(`is_deleted` ASC) USING BTREE,
  INDEX `idx_sort_order`(`sort_order` ASC) USING BTREE,
  INDEX `idx_view_count`(`view_count` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '交通标志表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of ap_traffic_sign
-- ----------------------------

-- ----------------------------
-- Table structure for ap_traffic_video
-- ----------------------------
DROP TABLE IF EXISTS `ap_traffic_video`;
CREATE TABLE `ap_traffic_video`  (
  `id` bigint NOT NULL COMMENT '视频ID，雪花算法生成',
  `video_title` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '视频标题',
  `video_desc` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '视频描述',
  `cover_image` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '封面图片URL',
  `video_url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '视频URL',
  `aliyun_video_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '阿里云视频ID',
  `play_auth` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '播放凭证',
  `video_duration` int NOT NULL DEFAULT 0 COMMENT '视频时长（秒）',
  `video_size` bigint NOT NULL DEFAULT 0 COMMENT '视频大小（字节）',
  `video_format` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'mp4' COMMENT '视频格式',
  `resolution` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '720p' COMMENT '分辨率',
  `category` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '视频分类',
  `tags` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '标签，逗号分隔',
  `instructor` varchar(164) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '讲师名称',
  `difficulty_level` tinyint NOT NULL DEFAULT 1 COMMENT '难度等级：1-初级，2-中级，3-高级',
  `is_vip` tinyint NOT NULL DEFAULT 0 COMMENT '是否VIP视频：0-免费，1-VIP',
  `is_hot` tinyint NOT NULL DEFAULT 0 COMMENT '是否热门：0-否，1-是',
  `is_downloadable` tinyint NOT NULL DEFAULT 0 COMMENT '是否可下载：0-否，1-是',
  `view_count` bigint NOT NULL DEFAULT 0 COMMENT '观看次数',
  `like_count` bigint NOT NULL DEFAULT 0 COMMENT '点赞次数',
  `share_count` bigint NOT NULL DEFAULT 0 COMMENT '分享次数',
  `comment_count` bigint NOT NULL DEFAULT 0 COMMENT '评论数',
  `download_count` bigint NOT NULL DEFAULT 0 COMMENT '下载次数',
  `rating` decimal(3, 2) NOT NULL DEFAULT 0.00 COMMENT '评分(0-5)',
  `rating_count` int NOT NULL DEFAULT 0 COMMENT '评分人数',
  `sort_order` int NOT NULL DEFAULT 0 COMMENT '排序权重',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '视频状态：0-下架，1-正常，2-审核中，3-转码中',
  `upload_user_id` bigint NULL DEFAULT NULL COMMENT '上传用户ID',
  `audit_user_id` bigint NULL DEFAULT NULL COMMENT '审核用户ID',
  `audit_time` datetime NULL DEFAULT NULL COMMENT '审核时间',
  `publish_time` datetime NULL DEFAULT NULL COMMENT '发布时间',
  `is_deleted` tinyint NOT NULL DEFAULT 0 COMMENT '是否删除：0-未删除，1-已删除',
  `gmt_create` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `gmt_modified` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_aliyun_video_id`(`aliyun_video_id` ASC) USING BTREE,
  INDEX `idx_category`(`category` ASC) USING BTREE,
  INDEX `idx_is_vip`(`is_vip` ASC) USING BTREE,
  INDEX `idx_is_hot`(`is_hot` ASC) USING BTREE,
  INDEX `idx_difficulty_level`(`difficulty_level` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE,
  INDEX `idx_sort_order`(`sort_order` ASC) USING BTREE,
  INDEX `idx_view_count`(`view_count` ASC) USING BTREE,
  INDEX `idx_like_count`(`like_count` ASC) USING BTREE,
  INDEX `idx_rating`(`rating` ASC) USING BTREE,
  INDEX `idx_publish_time`(`publish_time` ASC) USING BTREE,
  INDEX `idx_is_deleted`(`is_deleted` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '交规视频表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of ap_traffic_video
-- ----------------------------

-- ----------------------------
-- Table structure for ap_user
-- ----------------------------
DROP TABLE IF EXISTS `ap_user`;
CREATE TABLE `ap_user`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `username` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '用户名',
  `password` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '密码',
  `real_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '真实姓名',
  `avatar` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '头像',
  `phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '手机号',
  `email` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '邮箱',
  `gender` tinyint NULL DEFAULT 0 COMMENT '性别 0:未知 1:男 2:女',
  `status` tinyint NULL DEFAULT 1 COMMENT '状态 0:禁用 1:正常',
  `vip_level` tinyint NULL DEFAULT 0 COMMENT '是否为VIP',
  `vip_expire_time` datetime NULL DEFAULT NULL COMMENT 'VIP 会员到期时间',
  `integral` bigint NULL DEFAULT 0 COMMENT '积分',
  `last_integral_update` date NULL DEFAULT NULL COMMENT '积分最后更新时间',
  `last_login_time` datetime NULL DEFAULT NULL COMMENT '最后登录时间',
  `comment_permission` tinyint NULL DEFAULT 1 COMMENT '评论权限：0-禁止评论，1-允许评论',
  `violation_comment_count` int NULL DEFAULT 0 COMMENT '违规评论次数',
  `aichat_permission` tinyint NULL DEFAULT 0 COMMENT 'AI权限：false0-禁止AI，true 1-允许AI',
  `violation_aichat_count` int NULL DEFAULT 0 COMMENT '违规AI聊天次数',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_username`(`username` ASC) USING BTREE,
  INDEX `idx_phone`(`phone` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2122960226232098819 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '用户表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of ap_user
-- ----------------------------

-- ----------------------------
-- Table structure for ap_user_answer_record
-- ----------------------------
DROP TABLE IF EXISTS `ap_user_answer_record`;
CREATE TABLE `ap_user_answer_record`  (
  `id` bigint NOT NULL COMMENT '答题记录ID，雪花算法生成',
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `user_nickname` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '用户昵称（冗余）',
  `question_id` bigint NOT NULL COMMENT '题目ID',
  `subject` tinyint NOT NULL COMMENT '科目（冗余）',
  `question_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '题型代码（冗余）',
  `question_type_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '题型名称（冗余）',
  `question_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '题目内容（冗余）',
  `correct_answer` tinyint NOT NULL COMMENT '正确答案（冗余）',
  `user_answer` tinyint NULL DEFAULT NULL COMMENT '用户答案：1-A，2-B，3-C，4-D，NULL-未答',
  `is_correct` tinyint NULL DEFAULT NULL COMMENT '是否正确：0-错误，1-正确，NULL-未答',
  `answer_time` int NULL DEFAULT NULL COMMENT '答题用时（秒）',
  `test_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '测试类型：sequential-顺序刷题，random-随机考试',
  `exam_id` bigint NULL DEFAULT NULL COMMENT '考试ID（如果是考试答题）',
  `is_deleted` tinyint NOT NULL DEFAULT 0 COMMENT '是否删除：0-未删除，1-已删除',
  `gmt_create` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '答题时间',
  `gmt_modified` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_id`(`user_id` ASC) USING BTREE,
  INDEX `idx_question_id`(`question_id` ASC) USING BTREE,
  INDEX `idx_subject`(`subject` ASC) USING BTREE,
  INDEX `idx_test_type`(`test_type` ASC) USING BTREE,
  INDEX `idx_exam_id`(`exam_id` ASC) USING BTREE,
  INDEX `idx_gmt_create`(`gmt_create` ASC) USING BTREE,
  INDEX `idx_is_deleted`(`is_deleted` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '用户答题记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of ap_user_answer_record
