-- ----------------------------
-- Table structure for ap_user_like_record
-- ----------------------------
DROP TABLE IF EXISTS `ap_user_like_record`;
CREATE TABLE `ap_user_like_record`  (
  `id` bigint NOT NULL COMMENT '点赞ID，雪花算法生成',
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `target_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '点赞对象类型：comment-评论，video-视频',
  `target_id` bigint NOT NULL COMMENT '点赞对象ID',
  `is_like` tinyint NOT NULL DEFAULT 1 COMMENT '是否点赞：0-取消点赞，1-点赞',
  `is_deleted` tinyint NOT NULL DEFAULT 0 COMMENT '是否删除：0-未删除，1-已删除',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_user_target`(`user_id` ASC, `target_type` ASC, `target_id` ASC) USING BTREE,
  INDEX `idx_user_id`(`user_id` ASC) USING BTREE,
  INDEX `idx_target`(`target_type` ASC, `target_id` ASC) USING BTREE,
  INDEX `idx_is_deleted`(`is_deleted` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '用户点赞记录表' ROW_FORMAT = Dynamic;

