-- ----------------------------
-- Table structure for ap_user_login_log
-- ----------------------------
DROP TABLE IF EXISTS `ap_user_login_log`;
CREATE TABLE `ap_user_login_log`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `login_time` datetime NOT NULL COMMENT '登录时间',
  `login_ip` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '登录IP地址',
  `ip_location` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'IP地址归属地（省市区）',
  `longitude` decimal(10, 7) NULL DEFAULT NULL COMMENT '经度',
  `latitude` decimal(10, 7) NULL DEFAULT NULL COMMENT '纬度',
  `device_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '设备类型（mobile/desktop/tablet/miniprogram）',
  `device_brand` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '设备品牌（iPhone/Huawei/Xiaomi等）',
  `device_model` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '设备型号（iPhone 13/P50 Pro等）',
  `os_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '操作系统名称（iOS/Android/Windows）',
  `os_version` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '操作系统版本（15.0/12.0等）',
  `browser_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '浏览器名称（Safari/Chrome等）',
  `browser_version` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '浏览器版本',
  `platform` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '平台（mp-weixin/app-android/app-ios/h5）',
  `login_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '登录方式（wechat/phone/sms/password）',
  `user_agent` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '用户代理字符串（完整的User-Agent）',
  `session_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '会话ID',
  `login_status` tinyint(1) NULL DEFAULT 1 COMMENT '登录状态（1:成功 0:失败）',
  `fail_reason` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '登录失败原因',
  `is_risk_login` tinyint(1) NULL DEFAULT 0 COMMENT '是否风险登录（1:是 0:否）',
  `risk_level` tinyint(1) NULL DEFAULT 0 COMMENT '风险等级（0:正常 1:低风险 2:中风险 3:高风险）',
  `risk_desc` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '风险描述（具体的风险原因说明）',
  `device_fingerprint` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '设备指纹（用于设备识别）',
  `network_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '网络类型（wifi/4g/5g等）',
  `logout_time` datetime NULL DEFAULT NULL COMMENT '退出登录时间',
  `online_duration` int NULL DEFAULT NULL COMMENT '在线时长（秒）',
  `client_version` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '客户端版本号',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_id`(`user_id` ASC) USING BTREE COMMENT '用户ID索引',
  INDEX `idx_login_time`(`login_time` ASC) USING BTREE COMMENT '登录时间索引',
  INDEX `idx_login_ip`(`login_ip` ASC) USING BTREE COMMENT '登录IP索引',
  INDEX `idx_is_risk`(`is_risk_login` ASC) USING BTREE COMMENT '风险登录索引',
  INDEX `idx_platform`(`platform` ASC) USING BTREE COMMENT '平台索引',
  INDEX `idx_login_status`(`login_status` ASC) USING BTREE COMMENT '登录状态索引',
  INDEX `idx_user_time`(`user_id` ASC, `login_time` ASC) USING BTREE COMMENT '用户和时间复合索引',
  INDEX `idx_device_fingerprint`(`device_fingerprint` ASC) USING BTREE COMMENT '设备指纹索引'
) ENGINE = InnoDB AUTO_INCREMENT = 2122966606691229699 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '用户登录日志表' ROW_FORMAT = Dynamic;

