-- ----------------------------
-- Table structure for ap_user_study_record
-- ----------------------------
DROP TABLE IF EXISTS `ap_user_study_record`;
CREATE TABLE `ap_user_study_record`  (
  `id` bigint NOT NULL COMMENT '学习记录ID，雪花算法生成',
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `study_date` datetime NOT NULL COMMENT '学习日期',
  `subject` tinyint NOT NULL COMMENT '科目',
  `study_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '学习类型：sequential-顺序刷题，exam-模拟考试，wrong-错题练习',
  `total_questions` int NOT NULL DEFAULT 0 COMMENT '总题数',
  `correct_count` int NOT NULL DEFAULT 0 COMMENT '正确题数',
  `wrong_count` int NOT NULL DEFAULT 0 COMMENT '错误题数',
  `accuracy_rate` decimal(5, 2) NOT NULL DEFAULT 0.00 COMMENT '正确率',
  `study_time` int NOT NULL DEFAULT 0 COMMENT '学习时长（分钟）',
  `points_earned` int NOT NULL DEFAULT 0 COMMENT '获得积分',
  `is_deleted` tinyint NOT NULL DEFAULT 0 COMMENT '是否删除：0-未删除，1-已删除',
  `gmt_create` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `gmt_modified` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_user_date_subject_type`(`user_id` ASC, `study_date` ASC, `subject` ASC, `study_type` ASC) USING BTREE,
  INDEX `idx_user_id`(`user_id` ASC) USING BTREE,
  INDEX `idx_study_date`(`study_date` ASC) USING BTREE,
  INDEX `idx_subject`(`subject` ASC) USING BTREE,
  INDEX `idx_study_type`(`study_type` ASC) USING BTREE,
  INDEX `idx_is_deleted`(`is_deleted` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '学习记录表' ROW_FORMAT = Dynamic;

