-- Table structure for ap_user_wrong_collection_question
-- ----------------------------
DROP TABLE IF EXISTS `ap_user_wrong_collection_question`;
CREATE TABLE `ap_user_wrong_collection_question`  (
  `id` bigint NOT NULL COMMENT 'ID，雪花算法生成',
  `user_id` bigint NOT NULL COMMENT '用户ID',
