  `wrong_count` int NOT NULL DEFAULT 1 COMMENT '错误次数',
  `last_wrong_answer` tinyint NULL DEFAULT NULL COMMENT '最后一次错误答案',
  `is_mastered` tinyint NOT NULL DEFAULT 0 COMMENT '是否已掌握：0-未掌握，1-已掌握',
  `mastered_time` datetime NULL DEFAULT NULL COMMENT '掌握时间',
  `first_wrong_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '首次错误时间',
  `last_wrong_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '最后错误时间',
  `is_deleted` tinyint NOT NULL DEFAULT 0 COMMENT '是否删除：0-未删除，1-已删除',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_user_question`(`user_id` ASC, `question_id` ASC, `record_type` ASC) USING BTREE,
  INDEX `idx_user_id`(`user_id` ASC) USING BTREE,
  INDEX `idx_is_mastered`(`is_mastered` ASC) USING BTREE,
  INDEX `idx_wrong_count`(`wrong_count` ASC) USING BTREE,
  INDEX `idx_last_wrong_time`(`last_wrong_time` ASC) USING BTREE,
  INDEX `idx_is_deleted`(`is_deleted` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '用户收藏_错题本表' ROW_FORMAT = Dynamic;

