-- ----------------------------
-- Table structure for z_ap_ip_location_cache
-- ----------------------------
DROP TABLE IF EXISTS `z_ap_ip_location_cache`;
CREATE TABLE `z_ap_ip_location_cache`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `ip_address` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'IP地址',
  `country` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '国家',
  `province` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '省份',
  `city` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '城市',
  `district` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '区县',
  `isp` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '运营商（电信/联通/移动等）',
  `longitude` decimal(10, 7) NULL DEFAULT NULL COMMENT '经度',
  `latitude` decimal(10, 7) NULL DEFAULT NULL COMMENT '纬度',
  `location_desc` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '位置描述（完整的地址描述）',
  `data_source` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '数据来源（baidu/amap/ip138/ipapi等）',
  `accuracy` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '精度等级（city/district/street）',
  `query_count` int NULL DEFAULT 1 COMMENT '查询次数统计',
  `last_query_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '最后查询时间',
  `expire_time` datetime NULL DEFAULT NULL COMMENT '缓存过期时间',
  `is_valid` tinyint(1) NULL DEFAULT 1 COMMENT '是否有效（1:有效 0:无效）',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_ip`(`ip_address` ASC) USING BTREE COMMENT 'IP地址唯一索引',
  INDEX `idx_expire_time`(`expire_time` ASC) USING BTREE COMMENT '过期时间索引',
  INDEX `idx_location`(`province` ASC, `city` ASC) USING BTREE COMMENT '位置索引',
  INDEX `idx_data_source`(`data_source` ASC) USING BTREE COMMENT '数据来源索引',
  INDEX `idx_last_query`(`last_query_time` ASC) USING BTREE COMMENT '最后查询时间索引'
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'IP地址位置缓存表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of z_ap_ip_location_cache
-- ----------------------------

-- ----------------------------
-- Table structure for z_ap_user_favorite
-- ----------------------------
DROP TABLE IF EXISTS `z_ap_user_favorite`;
CREATE TABLE `z_ap_user_favorite`  (
  `id` bigint NOT NULL COMMENT '收藏ID，雪花算法生成',
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `question_id` bigint NOT NULL COMMENT '题目ID',
  `subject` tinyint NOT NULL COMMENT '科目（冗余）',
  `question_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '题型代码（冗余）',
  `question_type_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '题型名称（冗余）',
  `question_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '题目内容（冗余）',
  `question_image_url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '题目配图URL（冗余）',
  `is_deleted` tinyint NOT NULL DEFAULT 0 COMMENT '是否删除：0-未删除，1-已删除',
  `gmt_create` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '收藏时间',
  `gmt_modified` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_user_question`(`user_id` ASC, `question_id` ASC) USING BTREE,
  INDEX `idx_user_id`(`user_id` ASC) USING BTREE,
  INDEX `idx_subject`(`subject` ASC) USING BTREE,
  INDEX `idx_gmt_create`(`gmt_create` ASC) USING BTREE,
  INDEX `idx_is_deleted`(`is_deleted` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '用户收藏表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of z_ap_user_favorite
-- ----------------------------

SET FOREIGN_KEY_CHECKS = 1;
